'use client';

import { useEffect, useState } from 'react';
import { Billboard } from '@react-three/drei';
import * as THREE from 'three';

/** Banners in public/ui/titles, generated by scripts/gen-titles.mjs */
export const STAGE_TITLES = ['chu-tich', 'pho-chu-tich-1', 'pho-chu-tich-2'];

const GIFTER_TITLES = [
  'dai-bang', 'ong-chua', 'chu-bao-ve', 'dai-gia', 'thieu-gia',
  'tieu-thu', 'nu-hoang', 'hoang-tu', 'cong-chua', 'trum-bar',
  'dan-choi', 'vua-nhay', 'than-tai', 'dai-ca', 'chien-than',
  'sat-thu-tim', 'cao-thu', 'ba-chu', 'hiep-si', 'thanh-quay',
];

/** Same person always gets the same title, on every client and reconnect */
export function titleForUser(userId: string): string {
  let h = 0;
  for (let i = 0; i < userId.length; i++) h = (h * 31 + userId.charCodeAt(i)) | 0;
  return GIFTER_TITLES[Math.abs(h) % GIFTER_TITLES.length];
}

const cache = new Map<string, THREE.Texture | null>();

function useTitleTexture(slug: string) {
  const [, bump] = useState(0);
  useEffect(() => {
    if (cache.has(slug)) return;
    cache.set(slug, null);
    let cancelled = false;
    new THREE.TextureLoader().load(`/ui/titles/${slug}.png`, (tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.anisotropy = 8;
      cache.set(slug, tex);
      if (!cancelled) bump((v) => v + 1);
    });
    return () => {
      cancelled = true;
    };
  }, [slug]);
  return cache.get(slug) ?? null;
}

/** Ornate title banner floating above a name tag */
export default function TitleBadge({
  slug,
  position,
  width = 1.3,
}: {
  slug: string;
  position: [number, number, number];
  width?: number;
}) {
  const tex = useTitleTexture(slug);
  if (!tex) return null;
  const img = tex.image as { width: number; height: number };
  const height = width * (img.height / img.width);
  return (
    // Lift by half the height so `position` is the banner's bottom edge
    <Billboard position={[position[0], position[1] + height / 2, position[2]]}>
      <mesh>
        <planeGeometry args={[width, height]} />
        <meshBasicMaterial map={tex} transparent alphaTest={0.05} depthWrite={false} toneMapped={false} />
      </mesh>
    </Billboard>
  );
}
